<?php
require_once __DIR__.'/portal.php';
function rmmc_fines_staff(string $role):void{
    rmmc_require_roles($role);
    $rows=rmmc_new_ledger_available()?rmmc_all('SELECT f.*,e.title,s.student_number,s.firstname,s.lastname,(SELECT COALESCE(SUM(p.amount),0) FROM ite_fine_payments p WHERE p.fine_id=f.id) paid FROM ite_event_fines f JOIN events e ON e.id=f.event_id JOIN students s ON s.id=f.student_id ORDER BY f.created_at DESC LIMIT 150'):[];
    rmmc_shell_start('Fines & Payments',$role);
    ?><div class="welcome"><h1>Fines and payments</h1><p>Absence fine: ₱20 per missed required event. Payments are recorded and never inferred from a button click.</p></div><section class="panel"><?php if(!rmmc_new_ledger_available()):?><div class="notice error">Apply the database upgrade before recording payments.</div><?php endif;?><div class="table-scroll"><table class="data-table"><tr><th>Student</th><th>Event</th><th>Fine</th><th>Paid</th><th>Balance</th><th>Payment</th></tr><?php foreach($rows as $f):$balance=max(0,(float)$f['amount']-(float)$f['paid']);?><tr><td><?=rmmc_e($f['student_number'])?> · <?=rmmc_e($f['lastname'].', '.$f['firstname'])?></td><td><?=rmmc_e($f['title'])?></td><td>₱<?=number_format((float)$f['amount'],2)?></td><td>₱<?=number_format((float)$f['paid'],2)?></td><td>₱<?=number_format($balance,2)?></td><td><?php if($balance>.001):?><form action="fine_action.php" method="post" class="row" style="min-width:250px"><input type="hidden" name="csrf" value="<?=rmmc_e(rmmc_csrf())?>"><input type="hidden" name="fine_id" value="<?=(int)$f['id']?>"><input type="number" min="0.01" step="0.01" max="<?=rmmc_e(number_format($balance,2,'.',''))?>" name="amount" value="<?=number_format($balance,2,'.','')?>" required style="width:95px"><input name="reference" placeholder="Receipt reference" maxlength="120" required style="width:135px"><button>Record</button></form><?php else:?><?=rmmc_badge('Paid')?><?php endif;?></td></tr><?php endforeach;?></table></div><?php if(!$rows):?><p class="empty">No fines recorded in the new ledger.</p><?php endif;?></section><?php rmmc_shell_end();
}
function rmmc_fines_student():void{
    rmmc_require_roles('Student');$s=rmmc_student();if(!$s){http_response_code(404);exit('No profile');}
    $rows=rmmc_new_ledger_available()?rmmc_all('SELECT f.*,e.title,(SELECT COALESCE(SUM(amount),0) FROM ite_fine_payments WHERE fine_id=f.id) paid FROM ite_event_fines f JOIN events e ON e.id=f.event_id WHERE f.student_id=? ORDER BY f.created_at DESC','i',[(int)$s['id']]):[];
    $payments=rmmc_new_ledger_available()?rmmc_all('SELECT p.amount,p.reference,p.recorded_at,e.title FROM ite_fine_payments p JOIN ite_event_fines f ON f.id=p.fine_id JOIN events e ON e.id=f.event_id WHERE f.student_id=? ORDER BY p.recorded_at DESC','i',[(int)$s['id']]):[];
    rmmc_shell_start('My Fines','Student');?><div class="welcome"><h1>Fines and payment history</h1><p>Only authorized officers and administrators can record payments.</p></div><section class="panel"><h2>Event fines</h2><div class="table-scroll"><table class="data-table"><tr><th>Event</th><th>Reason</th><th>Amount</th><th>Paid</th><th>Balance</th></tr><?php foreach($rows as $f):?><tr><td><?=rmmc_e($f['title'])?></td><td><?=rmmc_e($f['reason'])?></td><td>₱<?=number_format((float)$f['amount'],2)?></td><td>₱<?=number_format((float)$f['paid'],2)?></td><td>₱<?=number_format(max(0,(float)$f['amount']-(float)$f['paid']),2)?></td></tr><?php endforeach;?></table></div><?php if(!$rows):?><p class="empty">No event fines recorded.</p><?php endif;?></section><section class="panel"><h2>Verified payments</h2><div class="table-scroll"><table class="data-table"><tr><th>Event</th><th>Amount</th><th>Reference</th><th>Date</th></tr><?php foreach($payments as $p):?><tr><td><?=rmmc_e($p['title'])?></td><td>₱<?=number_format((float)$p['amount'],2)?></td><td><?=rmmc_e($p['reference'])?></td><td><?=rmmc_e($p['recorded_at'])?></td></tr><?php endforeach;?></table></div><?php if(!$payments):?><p class="empty">No verified payments recorded.</p><?php endif;?></section><?php rmmc_shell_end();
}
